#include <vector>
using namespace std;

class Solution {
public:
    vector<int> numOfBurgers(int tomatoSlices, int cheeseSlices) {
        int x = tomatoSlices - 2 * cheeseSlices;
        if (x < 0 || x % 2 != 0) return {};
        int jumbo = x / 2;
        int small = cheeseSlices - jumbo;
        if (small < 0) return {};
        return {jumbo, small};
    }
};
